public struct Agent: Equatable, Hashable {
    public var at: AgentRef
    public var name: String
    public var workspaceName: String
    public var deviceName: String
    /**
     * The machine it runs on, by name.
     */
    public var machine: String
    public var program: Program?
    public var state: AgentState
    /**
     * When it entered its state.
     */
    public var since: UInt64?
    public var waiting: Waiting?
    public var canInterrupt: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(at: AgentRef, name: String, workspaceName: String, deviceName: String, 
        /**
         * The machine it runs on, by name.
         */machine: String, program: Program?, state: AgentState, 
        /**
         * When it entered its state.
         */since: UInt64?, waiting: Waiting?, canInterrupt: Bool) {
        self.at = at
        self.name = name
        self.workspaceName = workspaceName
        self.deviceName = deviceName
        self.machine = machine
        self.program = program
        self.state = state
        self.since = since
        self.waiting = waiting
        self.canInterrupt = canInterrupt
    }

    

    
}

