public enum AgentState: Equatable, Hashable {
    
    case idle
    case working
    case waiting
    case done
    case failed
    case interrupted
    case limited
    case exited





}

#if compiler(>=6)
extension AgentState: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAgentState: FfiConverterRustBuffer {
    typealias SwiftType = AgentState

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AgentState {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .idle
        
        case 2: return .working
        
        case 3: return .waiting
        
        case 4: return .done
        
        case 5: return .failed
        
        case 6: return .interrupted
        
        case 7: return .limited
        
        case 8: return .exited
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AgentState, into buf: inout [UInt8]) {
        switch value {
        
        
        case .idle:
            writeInt(&buf, Int32(1))
        
        
        case .working:
            writeInt(&buf, Int32(2))
        
        
        case .waiting:
            writeInt(&buf, Int32(3))
        
        
        case .done:
            writeInt(&buf, Int32(4))
        
        
        case .failed:
            writeInt(&buf, Int32(5))
        
        
        case .interrupted:
            writeInt(&buf, Int32(6))
        
        
        case .limited:
            writeInt(&buf, Int32(7))
        
        
        case .exited:
            writeInt(&buf, Int32(8))
        
        }
    }
}


